const cmds = [
  ["status", "rtk git status --short", 4000],
  ["diff", "rtk git diff -- crates/callisto-graph/src/locate/membership.rs crates/callisto-graph/src/locate/ignore_walk.rs crates/callisto-graph/src/locate/mod.rs", 30000],
  ["spec", "rtk bat --paging=never docs/specs/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json", 30000],
  ["project", "rtk bat --paging=never docs/projects/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json", 30000],
  ["files", "rtk bat --paging=never crates/callisto-graph/src/locate/membership.rs crates/callisto-graph/src/locate/ignore_walk.rs crates/callisto-graph/src/locate/mod.rs", 30000]
];
const results = await Promise.all(cmds.map(async ([name, cmd, max]) => {
  const r = await tools.exec_command({cmd, workdir:"/private/tmp/callisto-release-recovery", yield_time_ms:10000, max_output_tokens:max});
  return {name, output:r.output, exit_code:r.exit_code};
}));
for (const x of results) { text(`## ${x.name}\n${x.output}`); }

