use std::io::ErrorKind;
use std::path::{Path, PathBuf};

use callisto_model::ManifestFormat;
use globset::{GlobBuilder, GlobSet, GlobSetBuilder};

use crate::locate::LocateError;

pub(crate) enum MembershipAuthority<T> {
    Absent,
    Present(T),
}

pub(crate) struct NegatableGlobSet {
    positive: GlobSet,
    negative: GlobSet,
}

impl NegatableGlobSet {
    pub(crate) fn is_match(&self, path: &Path) -> bool {
        self.positive.is_match(path) && !self.negative.is_match(path)
    }

    fn empty() -> Self {
        Self {
            positive: GlobSet::empty(),
            negative: GlobSet::empty(),
        }
    }
}

#[derive(Clone, Copy)]
struct AuthorityPath {
    ecosystem: &'static str,
    path: &'static str,
}

impl AuthorityPath {
    fn relative_path(self) -> PathBuf {
        PathBuf::from(self.path)
    }

    fn field_error(self, field: &'static str, detail: &'static str) -> LocateError {
        LocateError::MembershipField {
            ecosystem: self.ecosystem,
            path: self.relative_path(),
            field,
            detail,
        }
    }
}

fn read_authority(root: &Path, authority: AuthorityPath) -> Result<Option<String>, LocateError> {
    let path = root.join(authority.path);
    match std::fs::read_to_string(&path) {
        Ok(content) => Ok(Some(content)),
        Err(error) if error.kind() == ErrorKind::NotFound => Ok(None),
        Err(error) => Err(LocateError::MembershipRead {
            ecosystem: authority.ecosystem,
            path: authority.relative_path(),
            message: error.to_string(),
        }),
    }
}

fn build_globset(
    entries: &[String],
    authority: AuthorityPath,
    field: &'static str,
) -> Result<NegatableGlobSet, LocateError> {
    let mut positive = GlobSetBuilder::new();
    let mut negative = GlobSetBuilder::new();
    for entry in entries {
        let (builder, pattern) = match entry.strip_prefix('!') {
            Some(rest) => (&mut negative, rest),
            None => (&mut positive, entry.as_str()),
        };
        let glob = GlobBuilder::new(pattern)
            .literal_separator(true)
            .build()
            .map_err(|error| LocateError::MembershipGlob {
                ecosystem: authority.ecosystem,
                path: authority.relative_path(),
                field,
                pattern: entry.clone(),
                message: error.to_string(),
            })?;
        builder.add(glob);
    }
    let positive = positive.build().map_err(|error| LocateError::MembershipGlob {
        ecosystem: authority.ecosystem,
        path: authority.relative_path(),
        field,
        pattern: "<compiled positive set>".to_string(),
        message: error.to_string(),
    })?;
    let negative = negative.build().map_err(|error| LocateError::MembershipGlob {
        ecosystem: authority.ecosystem,
        path: authority.relative_path(),
        field,
        pattern: "<compiled negative set>".to_string(),
        message: error.to_string(),
    })?;
    Ok(NegatableGlobSet { positive, negative })
}

pub(crate) struct Membership {
    members: Option<NegatableGlobSet>,
    exclude: NegatableGlobSet,
    hybrid_root: bool,
}

impl Membership {
    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
        if is_root && self.hybrid_root {
            return true;
        }
        !self.exclude.is_match(rel) && self.members.as_ref().is_none_or(|members| members.is_match(rel))
    }
}

pub(crate) struct MembershipSpec {
    manifest_file_name: &'static str,
    table_path: &'static [&'static str],
    owner_key: &'static str,
    ecosystem: &'static str,
}

pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::CargoToml.file_name(),
    table_path: &["workspace"],
    owner_key: "package",
    ecosystem: "Cargo",
};

pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
    table_path: &["tool", "uv", "workspace"],
    owner_key: "project",
    ecosystem: "uv",
};

fn membership_authority(spec: &MembershipSpec) -> AuthorityPath {
    AuthorityPath {
        ecosystem: spec.ecosystem,
        path: spec.manifest_file_name,
    }
}

fn table_at<'a>(
    doc: &'a toml_edit::DocumentMut,
    spec: &MembershipSpec,
    authority: AuthorityPath,
) -> Result<Option<&'a toml_edit::Item>, LocateError> {
    let mut item = match doc.get(spec.table_path[0]) {
        Some(item) => item,
        None => return Ok(None),
    };
    for key in spec.table_path.iter().skip(1) {
        if item.as_table_like().is_none() {
            return Err(authority.field_error("workspace", "must be a table containing the workspace authority"));
        }
        item = match item.get(*key) {
            Some(item) => item,
            None => return Ok(None),
        };
    }
    if item.as_table_like().is_none() {
        return Err(authority.field_error("workspace", "must be a workspace table"));
    }
    Ok(Some(item))
}

fn parse_toml_string_array(
    item: &toml_edit::Item,
    authority: AuthorityPath,
    field: &'static str,
) -> Result<Vec<String>, LocateError> {
    let array = item
        .as_array()
        .ok_or_else(|| authority.field_error(field, "must be an array of strings"))?;
    array
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(ToOwned::to_owned)
                .ok_or_else(|| authority.field_error(field, "must contain only strings"))
        })
        .collect()
}

pub(crate) fn read_membership(
    root: &Path,
    spec: &MembershipSpec,
) -> Result<MembershipAuthority<Membership>, LocateError> {
    let authority = membership_authority(spec);
    let Some(content) = read_authority(root, authority)? else {
        return Ok(MembershipAuthority::Absent);
    };
    let doc = content
        .parse::<toml_edit::DocumentMut>()
        .map_err(|error| LocateError::MembershipParse {
            ecosystem: authority.ecosystem,
            path: authority.relative_path(),
            parser: "TOML",
            message: error.to_string(),
        })?;
    let Some(workspace) = table_at(&doc, spec, authority)? else {
        return Ok(MembershipAuthority::Absent);
    };
    let members = workspace
        .get("members")
        .map(|item| parse_toml_string_array(item, authority, "members"))
        .transpose()?
        .map(|entries| build_globset(&entries, authority, "members"))
        .transpose()?;
    let exclude = workspace
        .get("exclude")
        .map(|item| parse_toml_string_array(item, authority, "exclude"))
        .transpose()?
        .map(|entries| build_globset(&entries, authority, "exclude"))
        .transpose()?
        .unwrap_or_else(NegatableGlobSet::empty);
    Ok(MembershipAuthority::Present(Membership {
        members,
        exclude,
        hybrid_root: doc.get(spec.owner_key).is_some(),
    }))
}

pub(crate) fn read_cargo_membership(root: &Path) -> Result<MembershipAuthority<Membership>, LocateError> {
    read_membership(root, &CARGO_MEMBERSHIP_SPEC)
}

pub(crate) fn read_python_membership(root: &Path) -> Result<MembershipAuthority<Membership>, LocateError> {
    read_membership(root, &PYTHON_MEMBERSHIP_SPEC)
}

pub(crate) struct NpmMembership {
    globs: NegatableGlobSet,
    hybrid_root: bool,
}

impl NpmMembership {
    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
        (is_root && self.hybrid_root) || self.globs.is_match(rel)
    }
}

const PACKAGE_JSON_AUTHORITY: AuthorityPath = AuthorityPath {
    ecosystem: "npm",
    path: "package.json",
};
const PNPM_AUTHORITY: AuthorityPath = AuthorityPath {
    ecosystem: "pnpm",
    path: "pnpm-workspace.yaml",
};

struct PackageJsonMembership {
    packages: Option<Vec<String>>,
    hybrid_root: bool,
}

fn read_package_json_membership(root: &Path) -> Result<MembershipAuthority<PackageJsonMembership>, LocateError> {
    let Some(content) = read_authority(root, PACKAGE_JSON_AUTHORITY)? else {
        return Ok(MembershipAuthority::Absent);
    };
    let value = serde_json::from_str::<serde_json::Value>(&content).map_err(|error| LocateError::MembershipParse {
        ecosystem: PACKAGE_JSON_AUTHORITY.ecosystem,
        path: PACKAGE_JSON_AUTHORITY.relative_path(),
        parser: "JSON",
        message: error.to_string(),
    })?;
    let packages = value
        .get("workspaces")
        .map(|field| {
            field
                .as_array()
                .ok_or_else(|| PACKAGE_JSON_AUTHORITY.field_error("workspaces", "must be an array of strings"))?
                .iter()
                .map(|item| {
                    item.as_str()
                        .map(ToOwned::to_owned)
                        .ok_or_else(|| PACKAGE_JSON_AUTHORITY.field_error("workspaces", "must contain only strings"))
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .transpose()?;
    Ok(MembershipAuthority::Present(PackageJsonMembership {
        packages,
        hybrid_root: value.get("name").is_some(),
    }))
}

fn read_pnpm_membership(root: &Path) -> Result<MembershipAuthority<Vec<String>>, LocateError> {
    let Some(content) = read_authority(root, PNPM_AUTHORITY)? else {
        return Ok(MembershipAuthority::Absent);
    };
    let documents = yaml_rust2::YamlLoader::load_from_str(&content).map_err(|error| LocateError::MembershipParse {
        ecosystem: PNPM_AUTHORITY.ecosystem,
        path: PNPM_AUTHORITY.relative_path(),
        parser: "YAML",
        message: error.to_string(),
    })?;
    let document = documents
        .first()
        .ok_or_else(|| PNPM_AUTHORITY.field_error("document", "must contain one YAML mapping document"))?;
    if document.as_hash().is_none() {
        return Err(PNPM_AUTHORITY.field_error("document", "must be a YAML mapping"));
    }
    let packages = match &document["packages"] {
        yaml_rust2::Yaml::BadValue => Vec::new(),
        yaml_rust2::Yaml::Array(items) => items
            .iter()
            .map(|item| {
                item.as_str()
                    .map(ToOwned::to_owned)
                    .ok_or_else(|| PNPM_AUTHORITY.field_error("packages", "must contain only strings"))
            })
            .collect::<Result<Vec<_>, _>>()?,
        _ => return Err(PNPM_AUTHORITY.field_error("packages", "must be an array of strings")),
    };
    Ok(MembershipAuthority::Present(packages))
}

pub(crate) fn read_npm_membership(root: &Path) -> Result<MembershipAuthority<NpmMembership>, LocateError> {
    let pnpm = read_pnpm_membership(root)?;
    let package_json = read_package_json_membership(root)?;
    match pnpm {
        MembershipAuthority::Present(packages) => {
            let hybrid_root = matches!(&package_json, MembershipAuthority::Present(package) if package.hybrid_root);
            Ok(MembershipAuthority::Present(NpmMembership {
                globs: build_globset(&packages, PNPM_AUTHORITY, "packages")?,
                hybrid_root,
            }))
        }
        MembershipAuthority::Absent => match package_json {
            MembershipAuthority::Absent => Ok(MembershipAuthority::Absent),
            MembershipAuthority::Present(package) => match package.packages {
                None => Ok(MembershipAuthority::Absent),
                Some(packages) => Ok(MembershipAuthority::Present(NpmMembership {
                    globs: build_globset(&packages, PACKAGE_JSON_AUTHORITY, "workspaces")?,
                    hybrid_root: package.hybrid_root,
                })),
            },
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    fn is_absent<T>(authority: MembershipAuthority<T>) -> bool {
        matches!(authority, MembershipAuthority::Absent)
    }

    fn admits(authority: MembershipAuthority<Membership>, path: &str, root: bool) -> bool {
        match authority {
            MembershipAuthority::Absent => true,
            MembershipAuthority::Present(membership) => membership.admits(Path::new(path), root),
        }
    }

    fn npm_admits(authority: MembershipAuthority<NpmMembership>, path: &str, root: bool) -> bool {
        match authority {
            MembershipAuthority::Absent => true,
            MembershipAuthority::Present(membership) => membership.admits(Path::new(path), root),
        }
    }

    #[test]
    fn cargo_and_uv_authorities_preserve_absence_empty_exclusions_and_hybrid_roots() {
        for (name, file, member_path, spec) in [
            ("cargo", "Cargo.toml", "crates/kept", &CARGO_MEMBERSHIP_SPEC),
            ("uv", "pyproject.toml", "packages/kept", &PYTHON_MEMBERSHIP_SPEC),
        ] {
            let missing = tempdir().unwrap();
            assert!(
                is_absent(read_membership(missing.path(), spec).unwrap()),
                "{name} missing authority"
            );

            let empty = tempdir().unwrap();
            let table = if name == "cargo" {
                "[workspace]"
            } else {
                "[tool.uv.workspace]"
            };
            std::fs::write(empty.path().join(file), format!("{table}\nmembers = []\n")).unwrap();
            assert!(
                !admits(read_membership(empty.path(), spec).unwrap(), member_path, false),
                "{name} empty members"
            );

            let included = tempdir().unwrap();
            std::fs::write(
                included.path().join(file),
                format!(
                    "{table}\nmembers = [\"{}/*\"]\nexclude = [\"{member_path}\"]\n",
                    member_path.split('/').next().unwrap()
                ),
            )
            .unwrap();
            assert!(
                !admits(read_membership(included.path(), spec).unwrap(), member_path, false),
                "{name} exclusion"
            );

            let hybrid = tempdir().unwrap();
            let owner = if name == "cargo" {
                "[package]\nname = \"root\"\nversion = \"0.1.0\""
            } else {
                "[project]\nname = \"root\"\nversion = \"0.1.0\""
            };
            std::fs::write(
                hybrid.path().join(file),
                format!("{owner}\n\n{table}\nmembers = []\nexclude = [\".\"]\n"),
            )
            .unwrap();
            assert!(
                admits(read_membership(hybrid.path(), spec).unwrap(), ".", true),
                "{name} hybrid root"
            );
        }
    }

    #[test]
    fn cargo_and_uv_malformed_authorities_fail_closed() {
        for (name, file, contents, spec) in [
            ("cargo syntax", "Cargo.toml", "[workspace", &CARGO_MEMBERSHIP_SPEC),
            (
                "uv syntax",
                "pyproject.toml",
                "[tool.uv.workspace",
                &PYTHON_MEMBERSHIP_SPEC,
            ),
            (
                "cargo shape",
                "Cargo.toml",
                "[workspace]\nmembers = \"crates/*\"",
                &CARGO_MEMBERSHIP_SPEC,
            ),
            (
                "uv item",
                "pyproject.toml",
                "[tool.uv.workspace]\nmembers = [\"packages/*\", 1]",
                &PYTHON_MEMBERSHIP_SPEC,
            ),
            (
                "cargo glob",
                "Cargo.toml",
                "[workspace]\nmembers = [\"crates/[\"]",
                &CARGO_MEMBERSHIP_SPEC,
            ),
        ] {
            let dir = tempdir().unwrap();
            std::fs::write(dir.path().join(file), contents).unwrap();
            assert!(read_membership(dir.path(), spec).is_err(), "{name} must fail closed");
        }
    }

    #[test]
    fn npm_and_pnpm_authorities_preserve_precedence_empty_and_root_only_omission() {
        let missing = tempdir().unwrap();
        assert!(is_absent(read_npm_membership(missing.path()).unwrap()));

        let empty = tempdir().unwrap();
        std::fs::write(empty.path().join("package.json"), r#"{"workspaces": []}"#).unwrap();
        assert!(!npm_admits(
            read_npm_membership(empty.path()).unwrap(),
            "packages/child",
            false
        ));

        let preferred = tempdir().unwrap();
        std::fs::write(
            preferred.path().join("package.json"),
            r#"{"workspaces": ["packages/*"]}"#,
        )
        .unwrap();
        std::fs::write(preferred.path().join("pnpm-workspace.yaml"), "packages:\n  - tools/*\n").unwrap();
        assert!(npm_admits(
            read_npm_membership(preferred.path()).unwrap(),
            "tools/kept",
            false
        ));
        assert!(!npm_admits(
            read_npm_membership(preferred.path()).unwrap(),
            "packages/child",
            false
        ));

        let omitted = tempdir().unwrap();
        std::fs::write(omitted.path().join("package.json"), r#"{"name": "root"}"#).unwrap();
        std::fs::write(
            omitted.path().join("pnpm-workspace.yaml"),
            "shared-workspace-lockfile: true\n",
        )
        .unwrap();
        assert!(npm_admits(read_npm_membership(omitted.path()).unwrap(), ".", true));
        assert!(!npm_admits(
            read_npm_membership(omitted.path()).unwrap(),
            "packages/child",
            false
        ));
    }

    #[test]
    fn npm_and_pnpm_malformed_authorities_fail_closed() {
        for (name, file, contents) in [
            ("npm syntax", "package.json", "{\"workspaces\": [}"),
            ("npm shape", "package.json", "{\"workspaces\": \"packages/*\"}"),
            ("npm item", "package.json", "{\"workspaces\": [\"packages/*\", 1]}"),
            ("npm glob", "package.json", "{\"workspaces\": [\"packages/[\"]}"),
            ("pnpm syntax", "pnpm-workspace.yaml", "packages: [\"packages/*\""),
            ("pnpm empty document", "pnpm-workspace.yaml", "# empty\n"),
            ("pnpm shape", "pnpm-workspace.yaml", "packages: packages/*\n"),
            ("pnpm item", "pnpm-workspace.yaml", "packages:\n  - packages/*\n  - 1\n"),
            ("pnpm glob", "pnpm-workspace.yaml", "packages:\n  - packages/[\n"),
        ] {
            let dir = tempdir().unwrap();
            std::fs::write(dir.path().join(file), contents).unwrap();
            assert!(read_npm_membership(dir.path()).is_err(), "{name} must fail closed");
        }
    }

    #[test]
    fn diagnostics_are_graph_owned_and_safe() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("Cargo.toml"), "[workspace]\nmembers = \"bad\"").unwrap();
        let error = match read_cargo_membership(dir.path()) {
            Ok(_) => panic!("malformed authority must fail"),
            Err(error) => error,
        };
        let message = error.to_string();
        assert!(message.contains("Cargo") && message.contains("Cargo.toml") && message.contains("members"));
        assert!(!message.contains("[workspace]"));
    }
}
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use callisto_model::{workspace_relative, Ecosystem, PackageId, ProjectRoot};
use ignore::WalkBuilder;

use crate::locate::membership;
use crate::locate::{find_workspace_root, LocateError, ProjectLocator};

pub struct IgnoreWalkLocator {
    root: PathBuf,
    skip: BTreeSet<&'static str>,
}

impl IgnoreWalkLocator {
    pub fn new(root: &Path) -> Self {
        let mut skip = BTreeSet::new();
        skip.insert("target");
        skip.insert("node_modules");
        skip.insert(".git");
        skip.insert(".moon");
        skip.insert("dist");

        let canonical = dunce::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
        IgnoreWalkLocator { root: canonical, skip }
    }

    pub fn discover(start: &Path) -> Result<Self, LocateError> {
        let root = find_workspace_root(start)?;
        Ok(Self::new(&root))
    }
}

impl ProjectLocator for IgnoreWalkLocator {
    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
        let mut results = Vec::new();
        let cargo_membership = membership::read_cargo_membership(&self.root)?;
        let npm_membership = membership::read_npm_membership(&self.root)?;
        let python_membership = membership::read_python_membership(&self.root)?;
        let walker = WalkBuilder::new(&self.root)
            .hidden(true)
            .git_ignore(true)
            .parents(false)
            .max_depth(Some(32))
            // Symlinked package directories (e.g. vendor-link style monorepos) are a
            // supported workspace pattern -- discovery follows them deliberately. The
            // existing max_depth(32) cap already bounds a symlink cycle from hanging.
            .follow_links(true)
            .filter_entry({
                let skip = self.skip.clone();
                move |entry| {
                    if let Some(name) = entry.file_name().to_str() {
                        if skip.contains(name) {
                            return false;
                        }
                    }
                    true
                }
            })
            .build();

        for entry_res in walker {
            let entry = entry_res.map_err(|e| LocateError::Walk {
                path: self.root.clone(),
                message: e.to_string(),
            })?;

            let path = entry.path();
            if !path.is_dir() {
                continue;
            }

            for ecosystem in Ecosystem::CANONICAL {
                // Every `Ecosystem::CANONICAL` member has a canonical
                // manifest format by construction -- see its doc comment.
                let format = ecosystem
                    .canonical_manifest_format()
                    .expect("CANONICAL ecosystems always have a canonical manifest format");
                let manifest_path = path.join(format.file_name());
                let Ok(content) = fs::read_to_string(&manifest_path) else {
                    continue;
                };
                let Ok(identity) = callisto_manifests::read_identity(format, &content, &manifest_path) else {
                    continue;
                };
                let Some(name) = identity.name else {
                    continue;
                };

                let rel = to_workspace_relative(path, &self.root)?;
                let is_root = rel == Path::new(".");
                let admitted = match ecosystem {
                    Ecosystem::Cargo => admits(&cargo_membership, &rel, is_root),
                    Ecosystem::Npm => admits(&npm_membership, &rel, is_root),
                    Ecosystem::Pypi => admits(&python_membership, &rel, is_root),
                    _ => false,
                };
                if admitted {
                    let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
                    results.push(ProjectRoot {
                        id,
                        path: rel,
                        ecosystem,
                    });
                }
            }
        }

        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
        Ok(results)
    }
}

fn admits<T>(authority: &membership::MembershipAuthority<T>, rel: &Path, is_root: bool) -> bool
where
    T: MembershipAdmits,
{
    match authority {
        membership::MembershipAuthority::Absent => true,
        membership::MembershipAuthority::Present(membership) => membership.admits(rel, is_root),
    }
}

trait MembershipAdmits {
    fn admits(&self, rel: &Path, is_root: bool) -> bool;
}

impl MembershipAdmits for membership::Membership {
    fn admits(&self, rel: &Path, is_root: bool) -> bool {
        self.admits(rel, is_root)
    }
}

impl MembershipAdmits for membership::NpmMembership {
    fn admits(&self, rel: &Path, is_root: bool) -> bool {
        self.admits(rel, is_root)
    }
}

fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
    if !path.starts_with(root) {
        return Err(LocateError::OutsideWorkspaceRoot {
            path: path.to_path_buf(),
            root: root.to_path_buf(),
        });
    }
    let rel = path.strip_prefix(root).unwrap();
    if rel.as_os_str().is_empty() {
        Ok(PathBuf::from("."))
    } else {
        workspace_relative(rel).map_err(|_e| LocateError::OutsideWorkspaceRoot {
            path: path.to_path_buf(),
            root: root.to_path_buf(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::tempdir;

    /// Spec: IgnoreWalkLocator must not traverse more than 32 directory levels
    /// deep. A Cargo.toml placed at level 33 must NOT be discovered.
    /// Without a max_depth cap, WalkBuilder traverses arbitrarily deep.
    #[test]
    fn ignore_walk_locator_does_not_traverse_beyond_32_levels() {
        let root = tempdir().unwrap();

        // Build a 33-level deep directory chain.
        let mut deep_dir = root.path().to_path_buf();
        for _ in 0..33 {
            deep_dir = deep_dir.join("sub");
        }
        fs::create_dir_all(&deep_dir).unwrap();

        // Place a valid Cargo.toml at the deepest level.
        fs::write(
            deep_dir.join("Cargo.toml"),
            "[package]\nname = \"deep-pkg\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root.path());
        let projects = locator.projects().unwrap();

        assert!(
            projects.is_empty(),
            "no projects should be found beyond 32 levels deep, found: {projects:?}"
        );
    }

    /// Spec: symlinked directories are a deliberately supported workspace
    /// pattern (vendor-link style monorepos). `IgnoreWalkLocator` must
    /// traverse *into* a symlinked directory and discover a package nested
    /// below its top level, not just a manifest sitting directly at the
    /// symlink's root -- proving `follow_links(true)` is really wired in,
    /// not just tolerated by an incidental `is_dir()` resolution.
    #[test]
    fn ignore_walk_locator_discovers_package_nested_inside_a_symlinked_directory() {
        let root = tempdir().unwrap();
        let external = tempdir().unwrap();

        let nested = external.path().join("nested-pkg");
        fs::create_dir_all(&nested).unwrap();
        fs::write(
            nested.join("Cargo.toml"),
            "[package]\nname = \"linked-nested-pkg\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();

        std::os::unix::fs::symlink(external.path(), root.path().join("vendor-link"))
            .expect("failed to create symlink for test fixture");

        let locator = IgnoreWalkLocator::new(root.path());
        let projects = locator.projects().unwrap();

        assert!(
            projects
                .iter()
                .any(|p| p.id == PackageId::Bare("linked-nested-pkg".to_string())),
            "expected linked-nested-pkg discovered through the symlinked directory, got: {projects:?}"
        );
    }

    /// Spec: a `pyproject.toml` workspace's `[tool.uv.workspace] exclude`
    /// entry must be honored by discovery, matching the Cargo/npm branches'
    /// own membership filtering -- a Python package under an excluded path
    /// must not be admitted as a release-managed package.
    #[test]
    fn ignore_walk_locator_honors_python_workspace_exclude() {
        let tmp = tempdir().unwrap();
        let root = tmp.path();
        fs::write(
            root.join("pyproject.toml"),
            "[project]\nname = \"root-pkg\"\nversion = \"0.1.0\"\n\n[tool.uv.workspace]\nmembers = [\"packages/*\"]\nexclude = [\"packages/examples/demo\"]\n",
        )
        .unwrap();
        fs::create_dir_all(root.join("packages/examples/demo")).unwrap();
        fs::write(
            root.join("packages/examples/demo/pyproject.toml"),
            "[project]\nname = \"demo\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();
        fs::create_dir_all(root.join("packages/kept")).unwrap();
        fs::write(
            root.join("packages/kept/pyproject.toml"),
            "[project]\nname = \"kept\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let projects = locator.projects().unwrap();

        assert!(
            !projects.iter().any(|p| p.path == Path::new("packages/examples/demo")),
            "excluded Python package must not be discovered, got: {projects:?}"
        );
        assert!(
            projects.iter().any(|p| p.path == Path::new("packages/kept")),
            "non-excluded Python package must still be discovered, got: {projects:?}"
        );
    }

