    /// AC-14 (npm slice): consolidated regression group reassembling the
    /// fixtures already proven individually (AC-09c malformed-workspaces
    /// fallback, AC-09e malformed-root-json fallback, AC-09g invalid-glob
    /// skip, AC-10 empty-workspaces-array excludes everything).
    /// Reassembles AC-14's exact fixtures into one regression group so
    /// future changes to npm membership handling that break any of these
    /// no-panic/fallback behaviors are caught here.
    #[test]
    fn ac14_npm_malformed_edge_case_regression_slice() {
        #[allow(unused_macros)]
        macro_rules! legacy_fallback_assertions {
            () => {
                // AC-09c: bare-string `workspaces` falls back to absent npm filter
                // (admits everything, including paths outside any glob).
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("package.json"), r#"{"workspaces": "packages/*"}"#).unwrap();
                    fs::create_dir_all(root.join("tools/outside")).unwrap();
                    fs::write(root.join("tools/outside/package.json"), r#"{"name":"outside"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects.iter().any(|p| p.path == Path::new("tools/outside")),
                        "AC-09c: tools/outside must be admitted, got: {projects:?}"
                    );
                }

                // AC-09e: syntactically invalid JSON falls back to absent npm
                // filter without panicking or erroring the whole walk.
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("package.json"), "{\"workspaces\": [\"packages/*\"],}").unwrap();
                    fs::create_dir_all(root.join("packages/kept")).unwrap();
                    fs::write(root.join("packages/kept/package.json"), r#"{"name":"kept"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects.iter().any(|p| p.path == Path::new("packages/kept")),
                        "AC-09e: packages/kept must be admitted, got: {projects:?}"
                    );
                }

                // AC-09g: an invalid glob entry in npm `workspaces` is skipped
                // without disabling sibling well-formed entries.
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(
                        root.join("package.json"),
                        r#"{"workspaces": ["packages/kept-example", "packages/[unterminated"]}"#,
                    )
                    .unwrap();
                    fs::create_dir_all(root.join("packages/kept-example")).unwrap();
                    fs::write(
                        root.join("packages/kept-example/package.json"),
                        r#"{"name":"kept-example"}"#,
                    )
                    .unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects
                            .iter()
                            .any(|p| p.path == Path::new("packages/kept-example")),
                        "AC-09g: packages/kept-example must be admitted, got: {projects:?}"
                    );
                }

                // AC-10: an explicitly empty `workspaces` array is a real
                // membership filter that matches nothing (distinguished from an
                // absent `workspaces` field).
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("package.json"), r#"{"workspaces": []}"#).unwrap();
                    fs::create_dir_all(root.join("packages/other")).unwrap();
                    fs::write(root.join("packages/other/package.json"), r#"{"name":"other"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        !projects.iter().any(|p| p.ecosystem == Ecosystem::Npm),
                        "AC-10: no Npm entries expected, got: {projects:?}"
                    );
                }
            };
        }
        for contents in [
            r#"{"workspaces": "packages/*"}"#,
            r#"{"workspaces": ["packages/*", 1]}"#,
            r#"{"workspaces": ["packages/["]}"#,
            "{\"workspaces\": [}",
        ] {
            let tmp = tempdir().unwrap();
            fs::write(tmp.path().join("package.json"), contents).unwrap();
            assert!(matches!(
                IgnoreWalkLocator::new(tmp.path()).projects(),
                Err(LocateError::MembershipField { .. })
                    | Err(LocateError::MembershipParse { .. })
                    | Err(LocateError::MembershipGlob { .. })
            ));
        }
    }

    /// AC-14 (pnpm slice): consolidated regression group reassembling the
    /// fixtures already proven individually (AC-09h invalid-glob skip
    /// TASK-25, AC-11 malformed-yaml-no-workspaces fallback TASK-27,
    /// AC-11b wrong-shape fallback TASK-28, AC-11d zero-yaml-documents
    /// fallback TASK-29). Reassembles AC-14's exact fixtures into one
    /// regression group so future changes to pnpm membership handling
    /// that break any of these no-panic/fallback behaviors are caught
    /// here.
    #[test]
    fn ac14_pnpm_malformed_edge_case_regression_slice() {
        #[allow(unused_macros)]
        macro_rules! legacy_fallback_assertions {
            () => {
                // AC-09h: an invalid glob entry in pnpm `packages` is skipped
                // without disabling sibling well-formed entries.
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(
                        root.join("pnpm-workspace.yaml"),
                        "packages:\n  - \"packages/kept-example\"\n  - \"packages/[unterminated\"\n",
                    )
                    .unwrap();
                    fs::create_dir_all(root.join("packages/kept-example")).unwrap();
                    fs::write(
                        root.join("packages/kept-example/package.json"),
                        r#"{"name":"kept-example"}"#,
                    )
                    .unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects
                            .iter()
                            .any(|p| p.path == Path::new("packages/kept-example")),
                        "AC-09h: packages/kept-example must be admitted, got: {projects:?}"
                    );
                }

                // AC-11: malformed pnpm-workspace.yaml (unterminated flow sequence)
                // with a root package.json present but lacking a "workspaces"
                // field falls back to admit-all npm membership without panicking
                // or erroring the whole walk.
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("package.json"), r#"{"name":"root"}"#).unwrap();
                    fs::write(root.join("pnpm-workspace.yaml"), "packages: [\"packages/*\"\n").unwrap();
                    fs::create_dir_all(root.join("packages/kept")).unwrap();
                    fs::write(root.join("packages/kept/package.json"), r#"{"name":"kept"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects.iter().any(|p| p.path == Path::new("packages/kept")),
                        "AC-11: packages/kept must be admitted, got: {projects:?}"
                    );
                }

                // AC-11b: pnpm-workspace.yaml parses successfully but `packages:`
                // is a bare scalar string, not a sequence -- falls back to absent
                // npm membership filter without panicking.
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("pnpm-workspace.yaml"), "packages: \"packages/*\"\n").unwrap();
                    fs::create_dir_all(root.join("packages/kept")).unwrap();
                    fs::write(root.join("packages/kept/package.json"), r#"{"name":"kept"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects.iter().any(|p| p.path == Path::new("packages/kept")),
                        "AC-11b: packages/kept must be admitted, got: {projects:?}"
                    );
                }

                // AC-11d: pnpm-workspace.yaml containing only YAML comments parses
                // successfully to zero documents (Ok(vec![])) -- falls back to
                // absent npm membership filter without unconditionally indexing
                // docs[0].
                {
                    let tmp = tempdir().unwrap();
                    let root = tmp.path();
                    fs::write(root.join("pnpm-workspace.yaml"), "# no packages here\n").unwrap();
                    fs::create_dir_all(root.join("packages/kept")).unwrap();
                    fs::write(root.join("packages/kept/package.json"), r#"{"name":"kept"}"#).unwrap();
                    let projects = IgnoreWalkLocator::new(root).projects().unwrap();
                    assert!(
                        projects.iter().any(|p| p.path == Path::new("packages/kept")),
                        "AC-11d: packages/kept must be admitted, got: {projects:?}"
                    );
                }
            };
        }
        for contents in [
            "packages: [\"packages/*\"",
            "packages: packages/*\n",
            "packages:\n  - packages/*\n  - 1\n",
            "packages:\n  - packages/[\n",
            "# empty\n",
        ] {
            let tmp = tempdir().unwrap();
            fs::write(tmp.path().join("pnpm-workspace.yaml"), contents).unwrap();
            assert!(matches!(
                IgnoreWalkLocator::new(tmp.path()).projects(),
                Err(LocateError::MembershipField { .. })
                    | Err(LocateError::MembershipParse { .. })
                    | Err(LocateError::MembershipGlob { .. })
            ));
        }
    }
}
use std::path::PathBuf;

use callisto_model::{DeclaredEdge, ProjectRoot};

pub mod ignore_walk;
mod membership;
pub mod root;

pub use ignore_walk::IgnoreWalkLocator;
pub use root::find_workspace_root;

pub trait ProjectLocator: Send + Sync {
    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError>;
    fn declared_edges(&self) -> Option<Vec<DeclaredEdge>> {
        None
    }
}

#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum LocateError {
    #[error("workspace root not found starting from `{start}`")]
    #[diagnostic(
        code(E030),
        help(
            "No workspace root found. Ensure the directory tree contains a workspace manifest: \
             Cargo.toml with [workspace], package.json with a workspaces field, \
             pnpm-workspace.yaml, or a .moon directory."
        )
    )]
    WorkspaceRootNotFound { start: PathBuf },

    #[error("failed to walk filesystem under `{path}`: {message}")]
    #[diagnostic(code(E031))]
    Walk { path: PathBuf, message: String },

    #[error("project path `{path}` is outside the workspace root `{root}`")]
    #[diagnostic(code(E032))]
    OutsideWorkspaceRoot { path: PathBuf, root: PathBuf },

    #[error("cannot read {ecosystem} workspace authority `{}`: {message}", .path.display())]
    #[diagnostic(
        code(E034),
        help(
            "Ensure this workspace authority file is readable, then retry discovery; Callisto did not scan without it."
        )
    )]
    MembershipRead {
        ecosystem: &'static str,
        path: PathBuf,
        message: String,
    },

    #[error("cannot parse {ecosystem} workspace authority `{}` as {parser}: {message}", .path.display())]
    #[diagnostic(
        code(E035),
        help("Fix the authority file syntax and retry discovery; Callisto did not scan without it.")
    )]
    MembershipParse {
        ecosystem: &'static str,
        path: PathBuf,
        parser: &'static str,
        message: String,
    },

    #[error("{ecosystem} workspace authority `{}` has invalid `{field}`: {detail}", .path.display())]
    #[diagnostic(
        code(E036),
        help("Use the documented workspace field shape and retry discovery; Callisto did not scan without it.")
    )]
    MembershipField {
        ecosystem: &'static str,
        path: PathBuf,
        field: &'static str,
        detail: &'static str,
    },

    #[error("{ecosystem} workspace authority `{}` has invalid `{field}` glob `{pattern}`: {message}", .path.display())]
    #[diagnostic(
        code(E037),
        help("Correct or remove the invalid workspace glob and retry discovery; Callisto did not scan without it.")
    )]
    MembershipGlob {
        ecosystem: &'static str,
        path: PathBuf,
        field: &'static str,
        pattern: String,
        message: String,
    },

    /// A VCS operation failed during workspace location. This variant exists
    /// so that callers who need to distinguish filesystem-structure errors
    /// (WorkspaceRootNotFound, Walk) from VCS errors (e.g., a git repository
    /// that could not be opened or queried during locate) can do so.
    #[error("VCS error during workspace location: {0}")]
    #[diagnostic(code(E033))]
    Vcs(Box<callisto_vcs::VcsError>),

    #[error("moon CLI is unavailable or exited non-zero")]
    MoonUnavailable,

    #[error("Failed to parse moon project-graph output: {message}")]
    MoonOutputParse { message: String },

    #[error("Incompatible moon version found: {found}, required: {required}")]
    IncompatibleMoonVersion { found: String, required: String },

    #[error(transparent)]
    Graph(#[from] Box<crate::error::GraphError>),
}

impl From<callisto_vcs::VcsError> for LocateError {
    fn from(e: callisto_vcs::VcsError) -> Self {
        LocateError::Vcs(Box::new(e))
    }
}

