            let hybrid = tempdir().unwrap();
            let owner = if name == "cargo" {
                "[package]\nname = \"root\"\nversion = \"0.1.0\""
            } else {
                "[project]\nname = \"root\"\nversion = \"0.1.0\""
            };
            std::fs::write(
                hybrid.path().join(file),
                format!("{owner}\n\n{table}\nmembers = []\nexclude = [\".\"]\n"),
            )
            .unwrap();
            assert!(
