            ("npm syntax", "package.json", "{\"workspaces\": [}"),
            ("npm shape", "package.json", "{\"workspaces\": \"packages/*\"}"),
            ("npm item", "package.json", "{\"workspaces\": [\"packages/*\", 1]}"),
            ("npm glob", "package.json", "{\"workspaces\": [\"packages/[\"]}"),
            ("pnpm syntax", "pnpm-workspace.yaml", "packages: [\"packages/*\""),
            ("pnpm empty document", "pnpm-workspace.yaml", "# empty\n"),
            ("pnpm shape", "pnpm-workspace.yaml", "packages: packages/*\n"),
            ("pnpm item", "pnpm-workspace.yaml", "packages:\n  - packages/*\n  - 1\n"),
            ("pnpm glob", "pnpm-workspace.yaml", "packages:\n  - packages/[\n"),
        ] {
            let dir = tempdir().unwrap();
            std::fs::write(dir.path().join(file), contents).unwrap();
            assert!(read_npm_membership(dir.path()).is_err(), "{name} must fail closed");
        }
    }

    #[test]
    fn diagnostics_are_graph_owned_and_safe() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("Cargo.toml"), "[workspace]\nmembers = \"bad\"").unwrap();
        let error = match read_cargo_membership(dir.path()) {
            Ok(_) => panic!("malformed authority must fail"),
            Err(error) => error,
        };
        let message = error.to_string();
        assert!(message.contains("Cargo") && message.contains("Cargo.toml") && message.contains("members"));
        assert!(!message.contains("[workspace]"));
    }

    #[test]
    fn parser_and_glob_diagnostics_retain_their_typed_sources() {
        use std::error::Error;

        for contents in ["[workspace", "[workspace]\nmembers = [\"crates/[\"]"] {
            let dir = tempdir().unwrap();
            std::fs::write(dir.path().join("Cargo.toml"), contents).unwrap();
            let error = match read_cargo_membership(dir.path()) {
                Ok(_) => panic!("malformed authority must fail"),
                Err(error) => error,
            };
            assert!(error.source().is_some());
        }
    }

    #[test]
    fn toml_miette_report_never_renders_manifest_contents() {
        use std::error::Error;

        let dir = tempdir().unwrap();
        let sentinel = "TOP_SECRET_TOML_SENTINEL";
        std::fs::write(
            dir.path().join("Cargo.toml"),
            format!("[workspace\nmembers = [\"{sentinel}\"]"),
        )
        .unwrap();
        let error = match read_cargo_membership(dir.path()) {
            Ok(_) => panic!("malformed authority must fail"),
            Err(error) => error,
        };
        assert!(error.source().is_some());
        let report = format!("{:?}", miette::Report::new(error));
        assert!(
            !report.contains(sentinel),
            "miette report leaked manifest content: {report}"
        );
    }

    #[test]
    fn io_json_and_yaml_diagnostics_retain_sources() {
        use std::error::Error;

        let io = tempdir().unwrap();
        std::fs::create_dir(io.path().join("Cargo.toml")).unwrap();
        let json = tempdir().unwrap();
        std::fs::write(json.path().join("package.json"), "{\"workspaces\": [}").unwrap();
        let yaml = tempdir().unwrap();
        std::fs::write(yaml.path().join("pnpm-workspace.yaml"), "packages: [").unwrap();
        for result in [
            read_cargo_membership(io.path()).map(|_| ()),
            read_npm_membership(json.path()).map(|_| ()),
            read_npm_membership(yaml.path()).map(|_| ()),
        ] {
            let error = result.expect_err("authority must fail");
            assert!(error.source().is_some());
        }
    }
